2	 *
3	 * WHY THIS EXISTS (F-012, measured 2026-09-08)
4	 * --------------------------------------------
5	 * scrollcraft's own docstring explains why the video playhead is damped:
6	 * "wheel events do not arrive at a constant rate and a 1:1 write reproduces
7	 * every gap in them." That reasoning is correct and the engine applies it to
8	 * exactly two things — video `currentTime` and pointer tilt/magnet. Everything
9	 * else `read()` writes is 1:1 with raw scroll position, including `--sc-p`
10	 * itself (scrollcraft.js line ~857). So any bespoke motion a page drives off
11	 * `--sc-p` — a card that flips, a light pool that travels, a word scrub —
12	 * steps at the wheel's notch rate on a Windows mouse. That is the "hackigt och
13	 * billigt" Anton saw in r7.
14	 *
15	 * F-011 did NOT cause it. Setting `var reduce = false` turned the playhead
16	 * lerp ON (rate 1.0 -> 0.18); it removed no smoothing. The stepping is
17	 * architectural and has always been there.
18	 *
19	 * Two further reasons a raw custom property cannot glide on its own:
20	 *   1. `--sc-p` is UNREGISTERED, so it is a string to CSS and never
21	 *      interpolates. `CSS.registerProperty` below fixes that for `--sc-ps`.
22	 *   2. scrollcraft.css sets `transition: none` on cues and copy once
23	 *      `.sc-ready` lands, deliberately, so nothing bridges per-event writes.
24	 *
25	 * THE RULE THIS FILE ENFORCES
26	 * ---------------------------
27	 * Bespoke motion reads `--sc-ps`, never `--sc-p`, whenever it drives something
28	 * the eye sees MOVE (transform, object-position, clip-path, mask-position).
29	 * Cue opacity may read `--sc-p`. See references/motion-smoothness.md.
30	 *
31	 * The engine is never edited (scroll/NOTE.md: copy, never edit). This file is
32	 * copied in beside it and loaded after it.
33	 */
34	(function () {
35	  'use strict';
36	
37	  var LERP = 0.16;      // per frame; 0.18 is the engine's playhead value, and a
38	                        // travelling element wants marginally more damping than
39	                        // a video seek because it has no decode latency of its own.
40	  var DEAD = 0.0005;    // below this the value has arrived; stop the loop.
41	
42	  // Register --sc-ps as a real number so CSS can interpolate it and so a page
43	  // may `transition: --sc-ps` if it wants belt and braces. Guarded: Safari
44	  // before 16.4 has no registerProperty, and re-registering the same name
45	  // throws, which must not take the page down.
46	  //
47	  // inherits MUST be true. The value is published on the act element and read
48	  // by its descendants — the card, the plate, the scrubbed word. Measured
49	  // 2026-09-08: with `inherits: false` a child reading var(--sc-ps) gets the
50	  // initial value 0, not the parent's, so the act would sit frozen at its
51	  // start state on every page while the console stayed clean. The engine's own
52	  // --sc-p is unregistered and therefore inherits by default; registering the
53	  // smoothed twin with different inheritance would have broken the contract it
54	  // exists to mirror.
55	  try {
56	    if (window.CSS && CSS.registerProperty) {
57	      CSS.registerProperty({
58	        name: '--sc-ps', syntax: '<number>', inherits: true, initialValue: '0'
59	      });
60	    }
61	  } catch (e) { /* already registered, or unsupported — the lerp still works */ }
62	
63	  var acts = [];
64	  var raf = null;
65	
66	  function collect() {
67	    acts = Array.prototype.map.call(
68	      document.querySelectorAll('[data-sc-act]'),
69	      function (el) { return { el: el, cur: NaN, last: '' }; }
70	    );
71	  }
72	
73	  function tick() {
74	    raf = null;
75	    var live = false;
76	    var frozen = !!window.__scFreezeMotion;
77	
78	    for (var i = 0; i < acts.length; i++) {
79	      var a = acts[i];
80	      var t = parseFloat(getComputedStyle(a.el).getPropertyValue('--sc-p'));
81	      if (isNaN(t)) continue;
82	      if (isNaN(a.cur)) a.cur = t;          // first frame: adopt, never animate in
83	
84	      if (frozen) {                          // ?preview= forces the formed state
85	        a.cur = t;
86	      } else {
87	        var d = t - a.cur;
88	        if (Math.abs(d) > DEAD) {
89	          a.cur += d * LERP;
90	          live = true;
91	        } else if (a.cur !== t) {
92	          a.cur = t;                         // snap the last sliver, no crawl
93	        }
94	      }
