96	      // Write ONLY when the value actually changed. A custom property written
97	      // on a parent recalculates style for every descendant, and an act is the
98	      // ancestor of its whole stage — so an unconditional per-frame write costs
99	      // a full subtree recalc for acts that are standing still, on every frame
100	      // any OTHER act happens to be moving.
101	      var next = a.cur.toFixed(4);
102	      if (next !== a.last) {
103	        a.el.style.setProperty('--sc-ps', next);
104	        a.last = next;
105	      }
106	    }
107	    if (live) raf = requestAnimationFrame(tick);
108	  }
109	
110	  function kick() { if (!raf) raf = requestAnimationFrame(tick); }
111	
112	  function start() {
113	    collect();
114	    kick();
115	    addEventListener('scroll', kick, { passive: true });
116	    addEventListener('resize', function () { collect(); kick(); }, { passive: true });
117	    // A late-arriving font changes act heights, which changes --sc-p without a
118	    // scroll event; adopt the new target rather than waiting for the reader.
119	    if (document.fonts && document.fonts.ready) {
