63:  --sc-section: clamp(4.5rem, 9vw, 11rem);
97:html { -webkit-text-size-adjust: 100%; scroll-behavior: smooth; }
100:body {
102:  background: var(--sc-canvas);
122::root { caret-color: var(--sc-accent); accent-color: var(--sc-accent); }
135:.sc-display {
