"""Uppatriktningen. motion_probe.py driver bara nedat; F-014:s bar kraver bada.

Scrollar till aktens slut, wheelar UPP med samma kadens, och matar samma tva tal:
staircase (varden som star stilla och sedan hoppar > 3 % av spannet) och max_step.
"""
import asyncio, json
from playwright.async_api import async_playwright

URL = "http://127.0.0.1:3302/tests/alunix-r8/runs/K3/index.html"

SAMPLE = """() => {
  const act = document.querySelector('section.act-drawing');
  const po  = document.getElementById('page-outline');
  const off = getComputedStyle(po).strokeDashoffset;
  return {
    ps: parseFloat(getComputedStyle(act).getPropertyValue('--sc-ps')) || 0,
    p:  parseFloat(getComputedStyle(act).getPropertyValue('--sc-p')) || 0,
    off: parseFloat(off) || 0
  };
}"""


def stats(vals):
    lo, hi = min(vals), max(vals)
    rng = (hi - lo) or 1.0
    steps = [abs(vals[i] - vals[i - 1]) / rng * 100 for i in range(1, len(vals))]
    stair = 0
    for i in range(1, len(steps)):
        if steps[i - 1] < 1e-9 and steps[i] > 3:
            stair += 1
    return {"range": [round(lo, 4), round(hi, 4)],
            "max_step_pct": round(max(steps), 2) if steps else 0,
            "staircase": stair, "samples": len(vals)}


async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch()
        pg = await b.new_page(viewport={"width": 1440, "height": 900})
        cdp = await pg.context.new_cdp_session(pg)
        await pg.goto(URL, wait_until="networkidle")
        await pg.wait_for_timeout(1000)
        await cdp.send("Emulation.setCPUThrottlingRate", {"rate": 4})
        results = {}
        for label, dy, ticks in (("100:60", -100, 40), ("20:120", -20, 60)):
            await pg.evaluate("window.scrollTo(0, 2900)")
            await pg.wait_for_timeout(900)
            rows = []
            for _ in range(ticks):
                await pg.mouse.wheel(0, dy)
                await pg.wait_for_timeout(60 if dy == -100 else 120)
                rows.append(await pg.evaluate(SAMPLE))
            results[label] = {
                "sc_p":  stats([r["p"] for r in rows]),
                "sc_ps": stats([r["ps"] for r in rows]),
                "page_outline_dashoffset": stats([r["off"] for r in rows]),
                "forsta": rows[0], "sista": rows[-1],
            }
        print(json.dumps(results, indent=1))
        await b.close()

asyncio.run(main())

